34	
35	import com.google.common.net.HostAndPort;
36	
37	import io.micrometer.core.instrument.MeterRegistry;
38	import io.micrometer.core.instrument.Metrics;
39	import io.micrometer.core.instrument.Tag;
40	import io.micrometer.core.instrument.binder.jvm.ClassLoaderMetrics;
41	import io.micrometer.core.instrument.binder.jvm.ExecutorServiceMetrics;
42	import io.micrometer.core.instrument.binder.jvm.JvmGcMetrics;
43	import io.micrometer.core.instrument.binder.jvm.JvmMemoryMetrics;
44	import io.micrometer.core.instrument.binder.jvm.JvmThreadMetrics;
45	import io.micrometer.core.instrument.binder.system.ProcessorMetrics;
46	
47	public class MetricsUtil {
48	
49	  private static final Logger LOG = LoggerFactory.getLogger(MetricsUtil.class);
50	
51	  private static JvmGcMetrics gc;
52	  private static List<Tag> commonTags;
53	  private static Pattern camelCasePattern = Pattern.compile("[a-z][A-Z][a-z]");
54	
55	  public static void initializeMetrics(final AccumuloConfiguration conf, final String appName,
56	      final HostAndPort address, final String instanceName, final String resourceGroup)
57	      throws ClassNotFoundException, InstantiationException, IllegalAccessException,
58	      IllegalArgumentException, InvocationTargetException, NoSuchMethodException,
59	      SecurityException {
60	    initializeMetrics(conf.getBoolean(Property.GENERAL_MICROMETER_ENABLED),
61	        conf.getBoolean(Property.GENERAL_MICROMETER_JVM_METRICS_ENABLED),
62	        conf.get(Property.GENERAL_MICROMETER_FACTORY), appName, address, instanceName,
63	        resourceGroup);
64	  }
65	
66	  private static void initializeMetrics(boolean enabled, boolean jvmMetricsEnabled,
67	      String factoryClass, String appName, HostAndPort address, String instanceName,
68	      String resourceGroup) throws ClassNotFoundException, InstantiationException,
69	      IllegalAccessException, IllegalArgumentException, InvocationTargetException,
70	      NoSuchMethodException, SecurityException {
71	
72	    LOG.info("initializing metrics, enabled:{}, class:{}", enabled, factoryClass);
73	
74	    if (enabled && factoryClass != null && !factoryClass.isEmpty()) {
75	
76	      String processName = appName;
77	      String serviceInstance = System.getProperty("accumulo.metrics.service.instance", "");
78	      if (!serviceInstance.isBlank()) {
79	        processName += serviceInstance;
80	      }
81	
82	      List<Tag> tags = new ArrayList<>();
83	      tags.add(Tag.of("instance.name", instanceName));
84	      tags.add(Tag.of("process.name", processName));
85	      tags.add(Tag.of("resource.group", resourceGroup));
86	      if (address != null) {
87	        if (!address.getHost().isEmpty()) {
88	          tags.add(Tag.of("host", address.getHost()));
89	        }
90	        if (address.getPort() > 0) {
91	          tags.add(Tag.of("port", Integer.toString(address.getPort())));
92	        }
93	      }
94	
95	      commonTags = Collections.unmodifiableList(tags);
96	
97	      Class<? extends MeterRegistryFactory> clazz =
98	          ClassLoaderUtil.loadClass(factoryClass, MeterRegistryFactory.class);
99	      MeterRegistryFactory factory = clazz.getDeclaredConstructor().newInstance();
100	
101	      MeterRegistry registry = factory.create();
102	      registry.config().commonTags(commonTags);
103	      Metrics.addRegistry(registry);
104	
105	      if (jvmMetricsEnabled) {
106	        new ClassLoaderMetrics(commonTags).bindTo(Metrics.globalRegistry);
107	        new JvmMemoryMetrics(commonTags).bindTo(Metrics.globalRegistry);
108	        gc = new JvmGcMetrics(commonTags);
109	        gc.bindTo(Metrics.globalRegistry);
110	        new ProcessorMetrics(commonTags).bindTo(Metrics.globalRegistry);
111	        new JvmThreadMetrics(commonTags).bindTo(Metrics.globalRegistry);
112	      }
113	    }
114	  }
115	
116	  public static void initializeProducers(MetricsProducer... producer) {
117	    for (MetricsProducer p : producer) {
118	      p.registerMetrics(Metrics.globalRegistry);
119	      LOG.info("Metric producer {} initialized", p.getClass().getSimpleName());
120	    }
121	  }
122	
123	  public static void addExecutorServiceMetrics(ExecutorService executor, String name) {
124	    new ExecutorServiceMetrics(executor, name, commonTags).bindTo(Metrics.globalRegistry);
125	  }
126	
127	  public static List<Tag> getCommonTags() {
128	    return commonTags;
129	  }
130	
131	  /**
132	   * Centralize any specific string formatting for metric names and/or tags. Ensure strings match
133	   * the micrometer naming convention.
134	   */
135	  public static String formatString(String name) {
136	
137	    // Handle spaces
138	    name = name.replace(" ", ".");
139	    // Handle snake_case notation
140	    name = name.replace("_", ".");
141	    // Handle Hyphens
142	    name = name.replace("-", ".");
143	
144	    // Handle camelCase notation
145	    Matcher matcher = camelCasePattern.matcher(name);
146	    StringBuilder output = new StringBuilder(name);
147	    int insertCount = 0;
148	    while (matcher.find()) {
149	      // Pattern matches at a lowercase letter, but the insert is at the second position.
150	      output.insert(matcher.start() + 1 + insertCount, ".");
151	      // The correct index position will shift as inserts occur.
152	      insertCount++;
153	    }
154	    name = output.toString();
155	    return name.toLowerCase();
156	  }
157	
158	  public static void close() {
159	    if (gc != null) {
160	      gc.close();
161	    }
162	  }
163	
164	}
