+  /**
+   * Updates the idle status of the server. A server is considered idle when it has no work to
+   * perform. The {@link MetricsProducer#METRICS_SERVER_IDLE} metric is emitted with a value of 1
+   * once the server has been continuously idle for at least
+   * {@link Property#GENERAL_IDLE_PROCESS_INTERVAL}.
+   *
+   * @param isIdle true if the server currently has no work to perform, false otherwise
+   */
+  public void updateIdleStatus(boolean isIdle) {
+    if (!isIdle) {
+      // The server is doing work, reset the idle period timer.
+      idlePeriodStartNanos = 0L;
+    } else if (idlePeriodStartNanos == 0L) {
+      // The server just became idle, start the idle period timer. Use a non-zero sentinel value
+      // when nanoTime happens to return 0 so that the timer is considered started.
+      long nanos = System.nanoTime();
+      idlePeriodStartNanos = (nanos == 0L) ? 1L : nanos;
+    }
+  }
+
+  /**
+   * @return true if the server has been continuously idle for at least
+   *         {@link Property#GENERAL_IDLE_PROCESS_INTERVAL}, false otherwise
+   */
+  public boolean isIdle() {
+    final long start = idlePeriodStartNanos;
+    if (start == 0L) {
+      return false;
+    }
+    return (System.nanoTime() - start) >= TimeUnit.MILLISECONDS.toNanos(idleReportingPeriodMillis);
+  }
+
   public String getHostname() {
     return hostname;
